const BASE_LNG = 128;
const BASE_LAT = 46;
const COS36 = 0.8090169944;
const SCALE = 50;

/**
 * 緯度・経度（lat, lng）を県ポリゴンと同一のSVG座標（x, y）へ投影変換する
 */
export function projectLatLngToMapXY(lat: number, lng: number): { x: number; y: number } {
  return {
    x: (lng - BASE_LNG) * COS36 * SCALE,
    y: (BASE_LAT - lat) * SCALE,
  };
}

